   624	def load_candidates_feed() -> list[dict[str, Any]]:
   625	    if not CANDIDATE_FEED_FILE.exists():
   626	        return []
   627	    try:
   628	        payload = json.loads(CANDIDATE_FEED_FILE.read_text(encoding="utf-8"))
   629	    except (OSError, json.JSONDecodeError):
   630	        return []
   631	    if not isinstance(payload, list):
   632	        return []
   633	
   634	    candidates: list[dict[str, Any]] = []
   635	    for row in payload:
   636	        if not isinstance(row, dict):
   637	            continue
   638	        mapped = map_candidate_payload(row)
   639	        if mapped is None:
   640	            continue
   641	        candidates.append(mapped)
   642	
   643	    candidates.sort(key=candidate_sort_key, reverse=True)
   644	    return candidates
