   700	def render_candidates_filter_script() -> str:
   701	    return """
   702	  <script>
   703	    (function () {
   704	      function normalizeText(value) {
   705	        return String(value || '')
   706	          .toLowerCase()
   707	          .normalize('NFD')
   708	          .replace(/[\\u0300-\\u036f]/g, '')
   709	          .replace(/đ/g, 'd')
   710	          .replace(/\\s+/g, ' ')
   711	          .trim();
   712	      }
   713	
   714	      function initCandidateFilter() {
   715	        var form = document.getElementById('candidateFilterForm');
   716	        var grid = document.getElementById('candidateListGrid');
   717	        if (!form || !grid) return;
   718	
   719	        var cards = Array.prototype.slice.call(grid.querySelectorAll('.jobs-candidate-list-card'));
   720	        var countLabel = document.getElementById('candidateFilterCount');
   721	        var searchInput = document.getElementById('candidateFilterSearch');
   722	        var locationSelect = document.getElementById('candidateFilterLocation');
   723	        var experienceSelect = document.getElementById('candidateFilterExperience');
   724	        var sortSelect = document.getElementById('candidateSortOrder');
   725	        var resetBtn = document.getElementById('candidateFilterReset');
   726	        var emptyState = document.getElementById('candidateEmptyState');
   727	        var pagination = document.getElementById('candidatePagination');
   728	        var paginationPages = document.getElementById('candidatePaginationPages');
   729	        var paginationPrev = pagination ? pagination.querySelector('[data-page-action=\"prev\"]') : null;
   730	        var paginationNext = pagination ? pagination.querySelector('[data-page-action=\"next\"]') : null;
   731	        var pageSize = 8;
   732	        var currentPage = 1;
   733	        var totalPages = 1;
   734	
   735	        function compareCards(a, b, sortValue) {
   736	          var aFeatured = Number(a.dataset.featured || 0);
   737	          var bFeatured = Number(b.dataset.featured || 0);
   738	          var aUpdated = Date.parse(a.dataset.updatedDate || '') || 0;
   739	          var bUpdated = Date.parse(b.dataset.updatedDate || '') || 0;
   740	          var aName = normalizeText((a.querySelector('h3') || {}).textContent || '');
   741	          var bName = normalizeText((b.querySelector('h3') || {}).textContent || '');
   742	
   743	          if (sortValue === 'name-asc') {
   744	            return aName.localeCompare(bName, 'vi');
   745	          }
   746	
   747	          if (sortValue === 'featured-first') {
   748	            return bFeatured - aFeatured || bUpdated - aUpdated || aName.localeCompare(bName, 'vi');
   749	          }
   750	
   751	          return bUpdated - aUpdated || bFeatured - aFeatured || aName.localeCompare(bName, 'vi');
   752	        }
   753	
   754	        function renderPagination(totalItems) {
   755	          if (!pagination || !paginationPages || !paginationPrev || !paginationNext) return;
   756	          totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
   757	          if (currentPage > totalPages) currentPage = totalPages;
   758	
   759	          if (totalItems <= pageSize) {
   760	            pagination.hidden = true;
   761	            paginationPages.innerHTML = '';
   762	            return;
   763	          }
   764	
   765	          pagination.hidden = false;
   766	          var buttons = [];
   767	          for (var page = 1; page <= totalPages; page += 1) {
   768	            buttons.push('<button type=\"button\" class=\"jobs-pagination-page' + (page === currentPage ? ' is-active' : '') + '\" data-page-number=\"' + page + '\">' + page + '</button>');
   769	          }
   770	          paginationPages.innerHTML = buttons.join('');
   771	          paginationPrev.disabled = currentPage <= 1;
   772	          paginationNext.disabled = currentPage >= totalPages;
   773	        }
   774	
   775	        function applyFilters(options) {
   776	          options = options || {};
   777	          var query = normalizeText(searchInput ? searchInput.value : '');
   778	          var location = normalizeText(locationSelect ? locationSelect.value : '');
   779	          var experience = normalizeText(experienceSelect ? experienceSelect.value : '');
   780	          var sortValue = sortSelect ? sortSelect.value : 'updated-desc';
   781	
   782	          var matched = cards.filter(function (card) {
   783	            var searchBlob = normalizeText(card.dataset.search || card.textContent || '');
   784	            var locationValue = normalizeText(card.dataset.location || '');
   785	            var experienceValue = normalizeText(card.dataset.experience || '');
   786	            var matchesQuery = !query || searchBlob.indexOf(query) !== -1;
   787	            var matchesLocation = !location || locationValue === location;
   788	            var matchesExperience = !experience || experienceValue === experience;
   789	            return matchesQuery && matchesLocation && matchesExperience;
   790	          });
   791	
   792	          matched.sort(function (a, b) { return compareCards(a, b, sortValue); });
   793	
   794	          if (!options.keepPage) currentPage = 1;
   795	          renderPagination(matched.length);
   796	
   797	          var pageStart = (currentPage - 1) * pageSize;
   798	          var pageEnd = pageStart + pageSize;
   799	          var visibleSlice = matched.slice(pageStart, pageEnd);
   800	          var visibleSet = new Set(visibleSlice);
   801	
   802	          cards.forEach(function (card) {
   803	            card.hidden = !visibleSet.has(card);
   804	          });
   805	
   806	          if (countLabel) {
   807	            countLabel.textContent = matched.length + ' hồ sơ phù hợp';
   808	          }
   809	          if (emptyState) {
   810	            emptyState.hidden = matched.length !== 0;
   811	          }
   812	        }
   813	
   814	        if (form) {
   815	          form.addEventListener('input', function () { applyFilters(); });
   816	          form.addEventListener('change', function () { applyFilters(); });
   817	        }
   818	
   819	        if (resetBtn) {
   820	          resetBtn.addEventListener('click', function () {
   821	            form.reset();
   822	            applyFilters();
   823	          });
   824	        }
   825	
   826	        if (paginationPages) {
   827	          paginationPages.addEventListener('click', function (event) {
   828	            var button = event.target.closest('[data-page-number]');
   829	            if (!button) return;
   830	            var nextPage = Number(button.dataset.pageNumber || '1');
   831	            if (!nextPage || nextPage === currentPage) return;
   832	            currentPage = nextPage;
   833	            applyFilters({ keepPage: true });
   834	          });
   835	        }
   836	
   837	        if (paginationPrev) {
   838	          paginationPrev.addEventListener('click', function () {
   839	            if (currentPage <= 1) return;
   840	            currentPage -= 1;
   841	            applyFilters({ keepPage: true });
   842	          });
   843	        }
   844	
   845	        if (paginationNext) {
   846	          paginationNext.addEventListener('click', function () {
   847	            if (currentPage >= totalPages) return;
   848	            currentPage += 1;
   849	            applyFilters({ keepPage: true });
   850	          });
   851	        }
   852	
   853	        applyFilters();
   854	      }
   855	
   856	      document.addEventListener('DOMContentLoaded', initCandidateFilter);
   857	    })();
   858	  </script>
   859	""".strip()
